// Original Rust School curriculum. Snippets are illustrative; they are not executed by this page.
// Some snippets omit surrounding functions, imports, Cargo features, or application-specific types.
const BOOK='https://doc.rust-lang.org/book/';
const CARGO='https://doc.rust-lang.org/cargo/';
const REF='https://doc.rust-lang.org/reference/';
const rotateQuiz=x=>{const shift=[...x.id].reduce((n,c)=>n+c.charCodeAt(0),0)%4;return{question:x.q,options:x.o.map((_,i)=>x.o[(i-shift+4)%4]),answer:((x.a||0)+shift)%4,explanation:x.why};};
const L=x=>({
 id:x.id,title:x.t,short:x.t,summary:x.s,minutes:x.level==='advanced'?12:9,level:x.level||'intermediate',
 goals:x.g,tip:x.tip,lab:x.lab||'ownership',source:x.src||BOOK,
 steps:[
  {label:'The problem',title:'Start with the problem',body:x.s,callout:'Make ownership, valid states, and failure behavior explicit before adding complexity.',phase:'source',code:x.c},
  {label:'The idea',title:x.t,body:x.i,callout:x.tip,phase:'check',code:x.c},
  {label:'The method',title:'Put the idea into code',body:x.m,callout:'This is an illustrative Rust snippet. Library examples may need imports, dependencies, and surrounding application code.',phase:'build',code:x.c},
  {label:'The result',title:'Read what the program means',body:x.r,callout:'Successful compilation establishes important guarantees, but tests still need to check the intended behavior.',phase:'run',code:x.c},
  {label:'Takeaway',title:'Make the idea stick',body:x.g.join('. ')+'. '+x.tip,callout:x.tip,phase:'recap',code:x.c}
 ],quiz:rotateQuiz(x)
});
const journey=L({id:'rust-journey',t:'How Rust Runs',level:'beginner',s:'Turn a small source file into a running program while seeing what the compiler checks before execution.',i:'Rust is compiled. The compiler checks types and borrowing rules, lowers the program, and generates target code. Cargo coordinates the package, dependencies, and build commands.',m:'Create a Cargo project, edit its main function, check it, and run it. Keep compiler errors separate from runtime failures: they happen at different stages.',r:'A successful build can reject many memory and concurrency mistakes before execution. It does not prove the algorithm, business rules, or external inputs are correct.',tip:'The compiler is a design partner, not a substitute for tests.',g:['Follow source through checking and compilation','Distinguish Cargo from the Rust compiler','Separate compile-time guarantees from runtime behavior'],c:'fn main() {\n    let language = "Rust";\n    println!("Hello, {language}!");\n}',q:'What does a successful Rust build establish?',o:['The code passed the compiler’s checks, not every behavioral requirement','The program cannot fail at runtime','Every algorithm is correct','All external services are available'],why:'Compilation checks language rules and important safety conditions. Runtime inputs, logic, and external systems still require validation.'});
journey.minutes=11;
journey.steps=[
 {label:'Write',title:'A program starts as text',body:'The source file declares a main function. It binds a string slice and asks println! to format it. The exclamation mark identifies a macro invocation.',callout:'Source code describes behavior; it is not yet the executable program.',phase:'source',code:'fn main() {\n    let language = "Rust";\n    println!("Hello, {language}!");\n}'},
 {label:'Package',title:'Cargo knows the project',body:'Cargo.toml records package metadata, edition, and dependencies. src/main.rs is the conventional root of a binary target. Cargo uses this information to coordinate compilation.',callout:'Cargo is the build and package tool. rustc is the compiler it invokes.',phase:'source',code:'// Terminal: cargo new hello_rust\n// Project: Cargo.toml and src/main.rs\nfn main() { println!("A new project"); }'},
 {label:'Check',title:'Catch mistakes before running',body:'cargo check performs compilation checks without producing the final executable in the usual build path. Type mismatches, invalid borrows, and use-after-move errors can be diagnosed here.',callout:'Read the first relevant error and its highlighted span before changing code.',phase:'check',code:'let count: u32 = 3;\n// let count: u32 = "three"; // type mismatch\nprintln!("{count}");'},
 {label:'Own',title:'Values have a responsible owner',body:'An owned String manages its allocation. Moving it into another binding transfers responsibility. The old binding cannot be used as though it still owned the value.',callout:'Ownership makes resource responsibility visible in the program.',phase:'check',code:'let original = String::from("hello");\nlet message = original;\nprintln!("{message}");\n// original is no longer usable here.'},
 {label:'Build',title:'Produce a target executable',body:'cargo build creates a binary for the selected target. The default development profile emphasizes an efficient edit-and-debug cycle. Release builds enable a different set of optimization defaults.',callout:'Build profiles affect compilation settings; they do not change the ownership rules.',phase:'build',code:'// Terminal: cargo build\n// Optimized profile: cargo build --release\nfn main() { println!("Built for this target"); }'},
 {label:'Run',title:'Now the behavior happens',body:'cargo run builds as needed and launches the binary. Formatting, file access, user input, and network failures happen while the program is running, not while source is being checked.',callout:'A program can be memory-safe and still return the wrong answer.',phase:'run',code:'fn main() {\n    let total = 20 + 22;\n    println!("Answer: {total}");\n}'},
 {label:'Verify',title:'Complete the feedback loop',body:'Add tests for intended behavior, format the code, and use lints to catch suspicious patterns. The daily loop is write, check, test, inspect, and improve.',callout:'Keep examples small enough to understand and tests specific enough to catch mistakes.',phase:'recap',code:'#[test]\nfn adds_two_numbers() {\n    assert_eq!(20 + 22, 42);\n}'}
];

export const modules=[
 {id:'getting-started',title:'Getting Started',color:'#b99b65',lessons:[journey,
 L({id:'rustup-toolchains',t:'Toolchains & rustup',level:'beginner',s:'A project needs a known compiler and tools, while your machine may host several Rust toolchains.',i:'rustup manages Rust toolchains and components. Stable, beta, and nightly are release channels. A project can select a toolchain without making every other project use the same one.',m:'Inspect the installed compiler and toolchain, then use a project toolchain file when reproducibility matters. Add components such as rustfmt and Clippy through the selected toolchain.',r:'A pinned toolchain improves repeatability, but dependencies, target libraries, linker configuration, and the lockfile also affect the build.',tip:'Use stable unless the project has a concrete reason to require unstable features.',g:['Distinguish a toolchain from a package','Inspect the selected compiler','Record project-specific toolchain requirements'],c:'// Terminal commands:\n// rustup show\n// rustc --version\n// cargo --version\n// rustup component add rustfmt clippy',q:'What is rustup responsible for?',o:['Managing Rust toolchains and components','Choosing your application’s business rules','Replacing every system linker','Publishing every crate automatically'],why:'rustup installs and selects compilers and related tools; Cargo manages package builds and dependencies.',src:'https://rust-lang.github.io/rustup/'}),
 L({id:'cargo-projects',t:'Cargo Projects & Targets',level:'beginner',s:'Organize code, dependencies, tests, and executable entry points without hand-writing compiler commands.',i:'A Cargo package is described by Cargo.toml and can contain targets such as a library, binaries, examples, and tests. A crate is a compilation unit; package and crate are related but different terms.',m:'Use src/lib.rs for reusable library code and src/main.rs for a binary entry point. Keep dependency declarations in the manifest and let Cargo resolve and build the graph.',r:'A thin binary can call a library, making logic easier to test and reuse. Large workspaces can coordinate multiple related packages.',tip:'Separate reusable behavior from command-line or service wiring.',g:['Identify packages and crate targets','Separate library logic from entry points','Use Cargo’s project conventions'],c:'// src/lib.rs\npub fn greeting(name: &str) -> String {\n    format!("Hello, {name}")\n}\n// A binary target can call this public function.',q:'What does src/lib.rs conventionally define?',o:['The root of a package’s library target','The only possible executable entry point','The compiler installation path','A dependency lockfile'],why:'Cargo recognizes src/lib.rs as the conventional library crate root.',src:CARGO}),
 L({id:'edition-2024',t:'Editions & Rust 2024',level:'beginner',s:'Adopt modern language rules while understanding how existing dependencies can continue to work.',i:'An edition selects a set of language compatibility rules for a crate. Rust 2024 became available with Rust 1.85. Editions are not compiler versions, and crates using different editions can work together.',m:'Set edition = "2024" in Cargo.toml for a compatible toolchain. For an existing project, follow the edition migration guide and review suggested changes rather than only editing the number.',r:'Edition migration preserves a path for language evolution. It does not automatically modernize every API or prove that unsafe declarations are correct.',tip:'A newer compiler and a newer edition are separate choices.',g:['Distinguish editions from compiler versions','Understand cross-edition dependencies','Review an edition migration'],c:'// Cargo.toml:\n// [package]\n// name = "rust_school"\n// edition = "2024"\nfn main() { println!("Edition-aware source"); }',q:'Can crates using different Rust editions depend on one another?',o:['Yes, editions are selected per crate','No, the entire ecosystem must migrate at once','Only if all crates are unsafe','Only without Cargo'],why:'Edition compatibility is designed to let crates from different editions interoperate.',src:'https://doc.rust-lang.org/edition-guide/rust-2024/index.html'}),
 L({id:'compiler-diagnostics',t:'Read Compiler Diagnostics',level:'beginner',s:'A compiler error contains more information than a red line: it points to the violated rule and often its cause.',i:'Diagnostics identify source spans, explain expected and actual types or ownership states, and may suggest changes. A suggestion is a starting point, not proof that the new design matches your intent.',m:'Reduce the example, read the first relevant diagnostic, and inspect related notes. Use rustc --explain with an error code when a longer explanation helps.',r:'Fixing an ownership error by cloning everywhere can compile while adding unnecessary work. Prefer understanding whether the function should own, share, or mutate the value.',tip:'Ask what the code is trying to own before accepting a mechanical fix.',g:['Read spans and related notes','Use error explanations','Choose a design-aware correction'],c:'let name = String::from("Ava");\nlet length = name.len();\nprintln!("{name} has {length} bytes");\n// Borrowing for len() keeps ownership here.',q:'What should you consider before adding clone() to fix a move error?',o:['Whether the API should borrow or transfer ownership','Only whether the line becomes shorter','Whether the error code is even','Whether all values live on the stack'],why:'A borrow or ownership transfer may express the intended relationship without duplicating data.',src:'https://doc.rust-lang.org/error_codes/'}),
 L({id:'build-profiles',t:'Debug & Release Builds',level:'beginner',s:'A program that is quick to compile during development may not be the best binary to benchmark or deploy.',i:'Cargo profiles configure optimization, debug information, and other build settings. Development and release defaults serve different workflows, and projects can customize them.',m:'Use the development profile while iterating and test an appropriate release build for performance measurements. Record relevant settings and target architecture when comparing results.',r:'Optimizations can change speed and binary size. Some checks, such as overflow checks under default profiles, differ, so specify arithmetic behavior explicitly when correctness depends on it.',tip:'Do not benchmark an accidental debug build and conclude the language is slow.',g:['Choose a profile for the task','Measure representative binaries','Make overflow behavior explicit'],c:'let maximum = u8::MAX;\nassert_eq!(maximum.checked_add(1), None);\nassert_eq!(maximum.wrapping_add(1), 0);\n// Terminal: cargo build --release',q:'Why use checked_add when overflow is a meaningful possibility?',o:['It reports overflow explicitly instead of relying on profile defaults','It always wraps to zero','It allocates a larger integer automatically','It disables type checking'],why:'checked_add returns an Option indicating whether the result fits the integer type.',src:'https://doc.rust-lang.org/cargo/reference/profiles.html'})
 ]},
 {id:'fundamentals',title:'Rust Fundamentals',color:'#439850',lessons:[
 L({id:'bindings-mutability',t:'Bindings & Mutability',level:'beginner',s:'Make clear which local values may change and which should remain stable.',i:'Bindings are immutable by default. mut permits reassignment or mutation through that binding when the type allows it. Shadowing creates a new binding and can change its type.',m:'Use mut only when a value needs to change. Use shadowing for a sequence of transformations when a new value naturally replaces the old meaning.',r:'Immutability can make reasoning easier, but it does not mean every value reachable through a binding is globally immutable; interior-mutability types have their own rules.',tip:'Prefer the narrowest scope that needs mutation.',g:['Declare intentional mutation','Distinguish reassignment from shadowing','Limit mutable state'],c:'let mut count = 0;\ncount += 1;\nlet input = " 42 ";\nlet input = input.trim();\nprintln!("{count}: {input}");',q:'What does shadowing do?',o:['Creates a new binding that can replace the visible name','Mutates every earlier copy of the value','Requires the original binding to be mutable','Always allocates heap memory'],why:'Shadowing introduces another binding, so it can change the type without mutating the old binding.'}),
 L({id:'scalar-types',t:'Numbers, Booleans & Characters',level:'beginner',s:'Choose representations that match the values your program can actually accept.',i:'Rust has explicit integer widths, floating-point types, bool, and char. A char represents a Unicode scalar value, not a byte and not necessarily a complete user-perceived character.',m:'Use suitable types, annotate when inference lacks context, and perform deliberate conversions. Check numeric parsing and overflow rather than assuming inputs fit.',r:'Floating-point calculations are approximate. Money and other exact decimal requirements may need a carefully chosen representation rather than casual f64 arithmetic.',tip:'A type choice is part of the domain model.',g:['Choose suitable scalar types','Distinguish chars from bytes','Handle conversions and limits deliberately'],c:'let retries: u8 = 3;\nlet distance: f64 = 12.5;\nlet ready: bool = true;\nlet symbol: char = \'λ\';\nprintln!("{retries} {distance} {ready} {symbol}");',q:'What does Rust char represent?',o:['A Unicode scalar value','Exactly one UTF-8 byte','An entire string','Any complete visual grapheme'],why:'A char is a Unicode scalar value. A user-perceived character can consist of multiple such values.'}),
 L({id:'tuples-arrays',t:'Tuples, Arrays & Slices',level:'beginner',lab:'borrowing',s:'Represent a fixed group of values or a sequence whose elements share a type.',i:'Tuples can hold different types at fixed positions. Arrays have a fixed length and one element type. A slice borrows a contiguous sequence without owning it.',m:'Use tuples for small fixed combinations and arrays when length belongs in the type. Accept slices when a function should work with data from arrays or vectors.',r:'An array’s length participates in its type, while a slice’s length is available at runtime. Indexing can panic when the index is out of bounds; get provides an Option.',tip:'A slice-based input often makes an API more flexible than an array-specific one.',g:['Distinguish fixed structures from sequences','Borrow arrays as slices','Choose checked element access'],c:'let point = (3, 4);\nlet values = [10, 20, 30];\nlet tail: &[i32] = &values[1..];\nassert_eq!(tail.get(0), Some(&20));\nprintln!("{}", point.0);',q:'Which function parameter can borrow elements from either an array or a Vec?',o:['&[T]','Only [T; 3]','Only String','Only usize'],why:'A slice reference describes a borrowed contiguous sequence independently of the owning container.'}),
 L({id:'control-flow',t:'Conditions & Loops',level:'beginner',lab:'iterators',s:'Express decisions and repeated work without hiding termination or boundary conditions.',i:'if is an expression whose branches must produce compatible types. loop, while, and for express different forms of repetition. A for loop obtains values from an iterator.',m:'Use ranges carefully: a..b excludes b, while a..=b includes it. Prefer iteration over values when manual indexing adds no useful information.',r:'Clear control flow makes edge cases easier to test. Loops still need correct termination and resource behavior; memory safety does not prevent an infinite loop.',tip:'State whether a boundary is inclusive before writing a range.',g:['Use expression-valued conditions','Choose a suitable loop','Read range boundaries accurately'],c:'let score = 82;\nlet result = if score >= 60 { "pass" } else { "retry" };\nfor attempt in 1..=3 {\n    println!("{attempt}: {result}");\n}',q:'Which values does 1..3 produce?',o:['1 and 2','1, 2, and 3','Only 3','0, 1, and 2'],why:'The upper bound of a..b is excluded.'}),
 L({id:'functions-expressions',t:'Functions & Expressions',level:'beginner',s:'Break behavior into small operations with clear inputs and outputs.',i:'Function signatures specify parameter and return types. A block can evaluate to its final expression without a semicolon; adding a semicolon usually turns that expression into a statement returning unit.',m:'Write a signature that describes the contract, then implement the smallest useful body. Use return when an early exit improves clarity rather than mechanically at every function end.',r:'Explicit signatures help both callers and the compiler understand a boundary. A good function name should describe behavior, not its implementation accident.',tip:'The difference between a final expression and a statement often explains an unexpected () type.',g:['Read a function contract','Return a block’s final expression','Use early exits deliberately'],c:'fn double(value: i32) -> i32 {\n    value * 2\n}\nlet answer = double(21);\nassert_eq!(answer, 42);',q:'What is returned by a block’s final expression without a semicolon?',o:['The value of that expression','Always zero','Always a String','A newly spawned thread'],why:'Rust blocks are expressions and can evaluate to their final unterminated expression.'}),
 L({id:'strings-slices',t:'String & str',level:'beginner',lab:'borrowing',s:'Pass text to a function without making an unnecessary owned copy.',i:'String owns a growable UTF-8 buffer. str is a string slice type, usually used behind a reference such as &str. A string literal is a borrowed string with static storage.',m:'Accept &str when a function only needs to read text. Return String when constructing new owned text. Borrow an existing String through an &str parameter.',r:'Borrowing avoids transferring ownership, but the source must remain valid for the duration of the borrow. UTF-8 does not permit arbitrary byte indexing as characters.',tip:'Use &str for read-only text inputs unless ownership is genuinely required.',g:['Distinguish owned and borrowed text','Design flexible text parameters','Avoid invalid UTF-8 indexing assumptions'],c:'fn greet(name: &str) -> String {\n    format!("Hello, {name}!")\n}\nlet name = String::from("Ava");\nprintln!("{}", greet(&name));',q:'Why is &str often a useful input type for a read-only text function?',o:['It can borrow literals and owned Strings without taking ownership','It automatically stores a permanent copy','It permits invalid UTF-8','It always requires a heap allocation'],why:'A borrowed string slice can refer to several forms of existing text without owning them.'})
 ]},
 {id:'ownership',title:'Ownership & Borrowing',color:'#8864bc',lessons:[
 L({id:'moves',t:'Moves & Ownership Transfer',level:'beginner',s:'A resource-owning value should not accidentally have two independent owners both trying to free it.',i:'Assigning or passing a non-Copy value commonly moves it. The destination receives ownership and the source binding can no longer be used as the owner. A move is a semantic transfer, not a promise about physical byte movement.',m:'Decide whether each function should own its argument or borrow it. Move values into consumers when they should control the remaining lifetime.',r:'The compiler tracks ownership across branches and calls. A moved value cannot be read again unless a new value is assigned to the binding in an appropriate way.',tip:'Ask who should be responsible for the value after a call returns.',g:['Trace ownership across assignments','Recognize consuming function parameters','Separate move semantics from copying allocations'],c:'fn consume(message: String) { println!("{message}"); }\nlet message = String::from("owned");\nconsume(message);\n// message has moved into consume.',q:'After a String is moved into a consuming function, what happens to the old binding?',o:['It cannot be used to access that moved value','It silently becomes an empty String','It owns a second allocation','It can be used until garbage collection'],why:'A move transfers ownership, and the compiler prevents later use through the old binding.'}),
 L({id:'copy-clone',t:'Copy vs Clone',level:'beginner',s:'Understand why assigning a small integer leaves it usable while assigning a String transfers ownership.',i:'Copy types support implicit duplication through ordinary assignment. Clone provides an explicit duplication operation that can perform work. A type implementing Drop cannot also implement Copy.',m:'Use cheap Copy values naturally. Call clone when a separate value is actually needed and consider its cost, especially for large buffers or nested collections.',r:'Clone does not universally mean a deep independent copy. Cloning an Rc or Arc creates another shared owner of the same allocation.',tip:'Read a type’s Clone semantics rather than assuming all clones behave alike.',g:['Recognize implicit Copy behavior','Use explicit Clone intentionally','Distinguish owned duplication from shared ownership'],c:'let count = 7_u32;\nlet other = count;\nlet name = String::from("Rust");\nlet duplicate = name.clone();\nprintln!("{count} {other} {name} {duplicate}");',q:'What does cloning an Arc typically do?',o:['Creates another shared owner of the same allocation','Deep-copies every nested object','Transfers ownership and invalidates the original','Makes non-thread-safe contents thread-safe'],why:'Arc::clone increments shared ownership; it does not duplicate the underlying value or change that value’s thread-safety requirements.'}),
 L({id:'drop-resources',t:'Drop & Resource Lifetimes',s:'Close resources predictably when the value responsible for them is no longer needed.',i:'Drop allows a type to perform cleanup as its owned value is dropped. Ownership supports resource management beyond memory, including files and lock guards. Cleanup timing follows ownership and scope rules, with important exceptions such as leaks or process abort.',m:'Let ordinary scope cleanup handle resources, or call std::mem::drop to end ownership early. Do not call a Drop::drop method directly.',r:'Destructors should not be the only mechanism for committing important external work. Process termination and panics can change which cleanup is possible.',tip:'Use explicit operations for fallible actions such as committing or flushing when the result matters.',g:['Connect ownership to cleanup','Release a value before scope end','Avoid treating destructors as guaranteed external transactions'],c:'struct Notice(&\'static str);\nimpl Drop for Notice {\n    fn drop(&mut self) { println!("dropping {}", self.0); }\n}\nlet notice = Notice("temporary");\ndrop(notice);',q:'How do you explicitly drop an owned value early?',o:['Call std::mem::drop(value)','Call value.drop() directly','Assign its pointer to zero','Wait for a garbage collector cycle'],why:'std::mem::drop takes ownership and lets the value be dropped; direct calls to Drop::drop are not allowed.'}),
 L({id:'shared-mutable-borrows',t:'Shared & Mutable Borrows',level:'beginner',lab:'borrowing',s:'Let functions inspect or modify a value without transferring ownership.',i:'&T provides shared access, while &mut T provides exclusive access under Rust’s borrowing rules. While an exclusive borrow is active, conflicting access through other references is not allowed.',m:'Use a shared reference for inspection and a mutable reference for changes. Keep borrow scopes narrow and let the caller retain ownership.',r:'These rules prevent many aliasing-related bugs. Interior mutability provides controlled exceptions through special types, not permission to ignore borrowing constraints.',tip:'An exclusive borrow describes access rights, not merely a variable with the mut keyword.',g:['Choose a reference from the required access','Keep ownership with the caller','Recognize conflicting simultaneous access'],c:'fn append_mark(text: &mut String) { text.push(\'!\'); }\nlet mut message = String::from("hello");\nlet length = message.len();\nappend_mark(&mut message);\nprintln!("{length}: {message}");',q:'What does &mut T primarily express?',o:['Exclusive access to the borrowed value under the borrowing rules','A permanent transfer of ownership','A guaranteed heap allocation','Permission for unlimited aliases to mutate'],why:'A mutable reference provides exclusive access for its valid borrowing duration.'}),
 L({id:'nonlexical-lifetimes',t:'Borrow Scopes & NLL',lab:'borrowing',s:'Read a value through a reference, then modify the owner after that reference is no longer needed.',i:'Non-lexical lifetime analysis lets many borrows end at their last relevant use rather than the end of the surrounding block. The compiler reasons about where the reference must remain usable.',m:'Finish reference-based work before taking a conflicting borrow. If the logic is unclear, introduce a smaller scope or return an owned result rather than fighting the checker.',r:'NLL does not make dangling references valid. A reference still cannot outlive the data it points to, and later uses can extend the required borrow.',tip:'Look for the last use of a reference, not only the closing brace.',g:['Track a borrow through its uses','Understand why a later mutation can be valid','Refactor overlapping access'],c:'let mut text = String::from("hello");\nlet view = &text;\nprintln!("{view}"); // last use of view\ntext.push(\'!\');\nprintln!("{text}");',q:'Why can text be mutated after the last use of view in this example?',o:['The shared borrow is no longer required there','All shared references permit mutation','String ignores borrowing rules','println! transfers ownership of text'],why:'The compiler can end the borrow after its last necessary use, permitting later non-conflicting access.'}),
 L({id:'borrowed-apis',t:'Design Borrowed APIs',lab:'lifetimes',s:'Return a useful view into input data without allocating or returning a dangling reference.',i:'A borrowed output must be tied to data owned elsewhere. A function cannot return a reference to a local owned String that will be dropped when the function returns.',m:'Return a slice of an input when that relationship is natural. Return an owned value when the result must outlive the input or is newly constructed.',r:'Borrowed APIs can avoid allocations, but they couple the caller’s usage to the source lifetime. Ownership can be a simpler and appropriate API boundary.',tip:'Choose borrowing for a real relationship, not as an unconditional performance rule.',g:['Tie borrowed output to existing data','Avoid returning references to local owners','Choose ownership when independence matters'],c:'fn first_word(text: &str) -> &str {\n    text.split_whitespace().next().unwrap_or("")\n}\nlet text = String::from("learn Rust");\nassert_eq!(first_word(&text), "learn");',q:'When is returning an owned String often the better choice?',o:['When the result must be independent of the input’s lifetime','Whenever the output is nonempty','Only when the caller uses unsafe','When a reference should point to a dropped local'],why:'An owned result can manage its own lifetime instead of borrowing from the caller’s input.'})
 ]},
 {id:'structs-enums',title:'Structs, Enums & Patterns',color:'#d58244',lessons:[
 L({id:'structs-methods',t:'Structs & Methods',level:'beginner',s:'Group related data and behavior into a type that expresses a domain concept.',i:'A struct names its fields. An impl block adds associated functions and methods. The receiver type—self, &self, or &mut self—communicates whether a method consumes, reads, or mutates the value.',m:'Use a constructor to establish sensible values and methods to express operations. Keep fields private when callers should preserve an invariant through the API.',r:'Encapsulation is useful when it protects meaningful rules, not merely when it creates more wrappers. Public API choices affect future compatibility.',tip:'Read a method receiver as an ownership contract.',g:['Group related fields','Choose a method receiver','Protect meaningful invariants'],c:'struct Rectangle { width: u32, height: u32 }\nimpl Rectangle {\n    fn area(&self) -> u32 { self.width * self.height }\n}\nlet shape = Rectangle { width: 4, height: 3 };\nassert_eq!(shape.area(), 12);',q:'What does an &self method receiver usually allow?',o:['Reading through a shared borrow without consuming the value','Taking ownership of the value','Unrestricted mutation of all fields','Returning a reference to any local variable'],why:'&self borrows the receiver for shared access; mutation requires appropriate interior-mutability mechanisms or a mutable receiver.'}),
 L({id:'enums-state',t:'Enums & Valid States',level:'beginner',s:'Represent one of several meaningful states without combining flags that permit impossible combinations.',i:'An enum has named variants, and each variant can carry its own data. This lets the type describe alternatives directly, such as pending versus completed work.',m:'Model distinct states as variants with only the data each state needs. Match on those variants when implementing behavior.',r:'A well-designed enum can make invalid combinations unrepresentable. It does not remove the need to validate data arriving from outside the program.',tip:'If several booleans describe one state machine, consider an enum.',g:['Represent alternatives explicitly','Attach data to the correct state','Reduce invalid combinations'],c:'enum Job { Pending, Done { output: String } }\nlet job = Job::Done { output: String::from("report") };\nmatch job {\n    Job::Pending => println!("waiting"),\n    Job::Done { output } => println!("{output}"),\n}',q:'Why use an enum for distinct application states?',o:['Each variant can carry only the data valid for that state','It prevents every runtime failure','It always uses less memory than a boolean','It makes all variants interchangeable'],why:'Enums model alternatives and their associated data, reducing meaningless field combinations.'}),
 L({id:'option',t:'Option & Missing Values',level:'beginner',s:'Represent a missing lookup result without pretending that an arbitrary sentinel value is ordinary data.',i:'Option<T> has Some(T) and None variants. It makes absence visible in a function’s return type, so callers must choose how to handle it.',m:'Use pattern matching or combinators such as map and unwrap_or for appropriate defaults. Use expect only when absence violates a documented invariant or is intentionally fatal.',r:'None is not an error by itself. It may be a normal outcome such as an empty iterator or a key that is not present.',tip:'Choose defaults that preserve the domain’s meaning rather than hiding missing data.',g:['Represent absence in the type','Handle both alternatives','Distinguish missing data from failure'],c:'let values = [10, 20];\nmatch values.get(5) {\n    Some(value) => println!("{value}"),\n    None => println!("No value at that index"),\n}',q:'What does Option<T> express?',o:['A value may be present or absent','A guaranteed allocation failure','A permanently uninitialized variable','A value that may have any unrelated type'],why:'Some contains a T, while None represents absence.'}),
 L({id:'match-if-let',t:'match, if let & let else',level:'beginner',s:'Handle an enum’s alternatives clearly while keeping a simple success path easy to read.',i:'match checks patterns and requires exhaustive coverage. if let is convenient when only one pattern needs special handling. let else extracts a pattern or leaves the current control-flow path.',m:'Use match when each alternative matters. Use let else for early exits in parsing or lookup code, ensuring the else branch diverges as required.',r:'A wildcard can make matching concise but can also hide newly added cases that deserve deliberate handling. Choose it intentionally.',tip:'Exhaustiveness is useful feedback when a type gains a new variant.',g:['Handle alternatives exhaustively','Use concise conditional destructuring','Keep the main path readable'],c:'fn print_first(values: &[i32]) {\n    let Some(first) = values.first() else { return; };\n    println!("{first}");\n}\nprint_first(&[4, 8]);',q:'What must the else branch of let else do?',o:['Diverge from the current path, such as by returning','Produce the same binding with a default type','Always panic','Always contain another match'],why:'The binding is only valid after a successful pattern, so the else path must not continue into its scope.'}),
 L({id:'patterns',t:'Patterns & Destructuring',lab:'borrowing',s:'Extract the parts of a value while controlling whether you move or borrow them.',i:'Patterns can destructure tuples, structs, enums, and slices. Binding modes matter: matching an owned value can move fields, while matching a reference often borrows through match ergonomics.',m:'Start from the access you need. Match &value for inspection, and consume the value only when the extracted fields should become owned elsewhere.',r:'A pattern is not just a text filter; it can establish bindings and ownership behavior. Guards add conditions after a pattern matches.',tip:'Before destructuring, decide whether the original value must remain usable.',g:['Read structural patterns','Control moves versus borrows','Use guards for additional conditions'],c:'let record = (String::from("Ava"), 23);\nlet (name, age) = &record;\nif *age >= 18 { println!("{name}"); }\nprintln!("{}", record.0);',q:'Why destructure &record instead of record when only inspecting an owned String field?',o:['To borrow the field and keep the original record usable','To clone every field automatically','To make the String a Copy type','To remove the field from memory'],why:'Borrowed destructuring avoids moving the String out of the original owner.'}),
 L({id:'modules-visibility',t:'Modules & Visibility',s:'Separate implementation details from the API other parts of a program should depend on.',i:'Modules organize names and visibility inside a crate. pub exposes an item according to its path; private items are restricted by Rust’s module privacy rules. use brings a path into scope without copying its value.',m:'Keep implementation helpers private and expose a small stable interface. Use pub(crate) when an item should be shared inside the crate but not outside it.',r:'A file layout supports module organization but is not identical to the public API. Re-exports can present a clean interface over internal modules.',tip:'Make visibility a deliberate contract, not the default response to an access error.',g:['Organize names into modules','Limit public surface area','Distinguish importing a name from owning a value'],c:'mod pricing {\n    pub(crate) fn total(unit: u32, count: u32) -> u32 { unit * count }\n}\nuse pricing::total;\nassert_eq!(total(4, 3), 12);',q:'What does pub(crate) mean?',o:['The item is visible within the current crate','The item is visible to every dependency’s private modules','The item is only visible on crates.io','The item is automatically serialized'],why:'pub(crate) restricts visibility to the containing crate.'})
 ]},
 {id:'collections-errors',title:'Collections & Errors',color:'#4689ba',lessons:[
 L({id:'vectors',t:'Vec & Dynamic Sequences',level:'beginner',lab:'iterators',s:'Store a sequence whose length changes while the program runs.',i:'Vec<T> owns a contiguous growable buffer. Its length counts initialized elements, while capacity describes allocated room. Growth can reallocate and invalidate pointers into the old allocation.',m:'Use push and pop to adjust the sequence and get for optional indexed access. Reserve capacity when a useful size estimate exists, but measure before over-optimizing.',r:'The borrow checker prevents safe references from surviving a conflicting mutation that could invalidate them. Raw pointers require separate care.',tip:'Length and capacity describe different properties.',g:['Manage a growable owned sequence','Choose appropriate access methods','Understand why growth affects references'],c:'let mut values = Vec::with_capacity(4);\nvalues.push(10);\nvalues.push(20);\nassert_eq!(values.len(), 2);\nassert_eq!(values.pop(), Some(20));',q:'What does Vec capacity describe?',o:['How many elements can fit before another allocation may be needed','How many elements are currently initialized','The maximum length forever','The number of references allowed'],why:'Capacity measures allocated room; len measures the elements currently in the vector.'}),
 L({id:'hashmaps',t:'HashMap & Entry APIs',lab:'iterators',s:'Count occurrences or look up values by keys rather than by a sequence position.',i:'HashMap<K, V> stores key-value associations using hashing and equality. Iteration order is not a stable sorting guarantee. The entry API combines lookup and insertion-oriented updates.',m:'Use entry with or_insert when accumulating counts. Choose borrowed lookup keys where supported, and use a sorted structure or explicit sorting when output order matters.',r:'A hash map’s performance depends on keys, hashing, and workload. It does not make every operation constant-time under all conditions.',tip:'Do not make a user-visible ordering depend on HashMap iteration order.',g:['Use key-based lookup','Update entries without redundant logic','Separate storage order from presentation order'],c:'use std::collections::HashMap;\nlet mut counts = HashMap::new();\nfor word in ["rust", "safe", "rust"] {\n    *counts.entry(word).or_insert(0) += 1;\n}\nassert_eq!(counts["rust"], 2);',q:'Why use the entry API when counting values?',o:['It supports inserting a default and updating an existing value through one entry','It sorts keys alphabetically','It removes the need for equality','It always clones the entire map'],why:'Entry APIs express the occupied-versus-vacant case directly and avoid scattered lookup-insert logic.'}),
 L({id:'unicode-text',t:'UTF-8 & Text Processing',lab:'iterators',s:'Process text that may contain characters encoded with more than one byte.',i:'String and str contain UTF-8. bytes() iterates encoded bytes; chars() iterates Unicode scalar values. Neither necessarily corresponds to user-perceived grapheme clusters.',m:'Use the representation the task actually needs. Slice strings only at valid UTF-8 boundaries, and use appropriate Unicode-aware libraries for grapheme-level or normalization-sensitive behavior.',r:'String length is measured in bytes. Counting chars does not always count what a user sees as a single character.',tip:'Specify whether an index or length counts bytes, scalar values, or graphemes.',g:['Distinguish text units','Avoid invalid byte slicing','Choose Unicode-aware operations deliberately'],c:'let text = "café";\nassert_eq!(text.len(), 5);\nassert_eq!(text.chars().count(), 4);\nlet prefix = text.get(..3).unwrap();\nassert_eq!(prefix, "caf");',q:'What does str::len() count?',o:['Bytes in the UTF-8 representation','User-perceived grapheme clusters','Always the same number as chars().count()','The number of allocated String objects'],why:'A string slice’s length is its byte length, which can differ from character-like counts.'}),
 L({id:'result',t:'Result & Recoverable Failure',level:'beginner',s:'Parsing and file access can fail for ordinary reasons that callers need to handle.',i:'Result<T, E> represents either Ok(T) or Err(E). It puts failure in the function contract instead of hiding it in an unchecked assumption.',m:'Match on a Result to recover, report, or propagate an error. Keep panic for conditions the API intentionally treats as unrecoverable or violated invariants.',r:'Returning Result does not decide the recovery policy. The caller or application boundary still needs to choose what to do.',tip:'An error type should carry enough information for a useful decision.',g:['Represent success and failure explicitly','Handle expected invalid input','Separate recoverable errors from panics'],c:'let parsed = "42".parse::<u32>();\nmatch parsed {\n    Ok(value) => println!("{value}"),\n    Err(error) => eprintln!("Invalid number: {error}"),\n}',q:'Which situation naturally fits Result?',o:['Parsing user-provided text that may be invalid','A guaranteed compile-time type mismatch','Declaring an immutable binding','Choosing an edition'],why:'Parsing can fail during normal runtime use, and Result lets the caller handle that failure.'}),
 L({id:'question-mark',t:'Propagate Errors with ?',s:'Keep a success path readable while returning failures to the caller with their meaning preserved.',i:'The ? operator unwraps a successful compatible result or returns early with its failure. For Result, error conversion can occur through the appropriate From relationship.',m:'Use ? inside a function whose return type supports the operation. Add context at meaningful boundaries instead of replacing every error with an unrelated string.',r:'? does not ignore an error and does not itself log it. It transfers responsibility to a caller, which must eventually handle the failure appropriately.',tip:'Propagate where you cannot decide; handle where you have the context to act.',g:['Read early error propagation','Choose compatible return types','Preserve useful error context'],c:'fn read_count(path: &str) -> Result<u32, Box<dyn std::error::Error>> {\n    let text = std::fs::read_to_string(path)?;\n    let count = text.trim().parse::<u32>()?;\n    Ok(count)\n}',q:'What does ? do when a Result is Err?',o:['Returns early from the enclosing function with a compatible error','Prints the error and continues','Converts the error into zero','Always panics'],why:'The operator propagates failure through the enclosing function’s compatible return type.'}),
 L({id:'error-design',t:'Design Useful Error Types',s:'A library caller needs to distinguish invalid input from an unavailable resource rather than parse a display message.',i:'Structured error variants preserve machine-readable categories. Display explains an error to a person, while std::error::Error can expose an underlying source. Application boundaries may use broader error aggregation than libraries.',m:'Define variants around decisions a caller may need to make. Keep sensitive internals out of public responses and retain diagnostic context in appropriate logs.',r:'A stable error API is part of compatibility. Converting every failure into one string loses useful structure and can make recovery brittle.',tip:'Design errors for the caller’s choices, not only for a convenient println!.',g:['Preserve failure categories','Separate display text from structure','Expose appropriate context without leaking details'],c:'#[derive(Debug)]\nenum ConfigError { MissingKey(String), InvalidPort(String) }\nfn parse_port(value: &str) -> Result<u16, ConfigError> {\n    value.parse().map_err(|_| ConfigError::InvalidPort(value.into()))\n}',q:'Why use structured error variants?',o:['Callers can distinguish cases without parsing human-readable text','They guarantee that no failure occurs','They remove the need for documentation','They make every error recoverable'],why:'Variants retain categories that code can match on while display text can evolve for human clarity.'})
 ]},
 {id:'traits-generics',title:'Traits, Generics & Lifetimes',color:'#399487',lessons:[
 L({id:'traits-bounds',t:'Traits & Behavior Bounds',lab:'lifetimes',s:'Write an operation that works with multiple types because they provide the behavior you need.',i:'A trait defines a set of associated behavior. A trait bound states which behavior a generic type must provide. Implementations connect concrete types to that contract.',m:'Name the capability rather than forcing every value into one concrete type. Keep bounds limited to what the function actually uses.',r:'Traits support reusable APIs, but a bound does not prove arbitrary business properties unless the contract and implementations establish them.',tip:'A good trait describes a coherent capability.',g:['Define shared behavior','Express required capabilities','Avoid unnecessary generic bounds'],c:'trait Named { fn name(&self) -> &str; }\nfn greet<T: Named>(value: &T) {\n    println!("Hello, {}", value.name());\n}',q:'What does T: Named require?',o:['T implements the Named trait','T has a field literally named Named','T must allocate a String','T must use dynamic dispatch'],why:'The bound requires the trait’s behavior to be implemented for the chosen type.'}),
 L({id:'generics',t:'Generic Functions & Types',lab:'lifetimes',s:'Reuse a data structure or algorithm while retaining type checking for each concrete use.',i:'Generics parameterize functions and types over other types or supported constants. Rust commonly generates specialized code for concrete generic instantiations, which can improve optimization while increasing code size.',m:'Keep the generic interface understandable and add bounds for the operations used. Prefer concrete types when generality adds complexity without a real caller need.',r:'A generic type is not an untyped box. Its uses remain checked, and incompatible types are rejected before execution.',tip:'Generalize a real pattern rather than every imaginable future use.',g:['Parameterize behavior safely','Use bounds for needed operations','Understand specialization tradeoffs'],c:'struct Pair<T> { first: T, second: T }\nfn choose_first<T>(pair: Pair<T>) -> T { pair.first }\nlet value = choose_first(Pair { first: 3, second: 4 });\nassert_eq!(value, 3);',q:'What remains true when using generics?',o:['Concrete uses are still statically type-checked','All values become dynamically typed','Ownership checking is disabled','Every generic value must be heap allocated'],why:'Generics preserve type relationships rather than replacing them with unchecked runtime values.'}),
 L({id:'associated-types',t:'Associated Types',lab:'iterators',s:'Describe a trait’s related type without making every use repeat an independent generic parameter.',i:'An associated type is chosen by a trait implementation. Iterator uses Item to describe what each call to next can yield. Generic trait parameters and associated types solve different API design problems.',m:'Use an associated type when the implementation naturally determines a related type. Specify it in bounds when callers need a particular relationship.',r:'Associated types improve readable contracts, especially when a type has one natural output for that trait implementation.',tip:'Read Iterator<Item = T> as a relationship, not as a separate container.',g:['Identify a trait’s related type','Read associated-type bounds','Distinguish implementation choices from caller parameters'],c:'fn sum_values<I>(values: I) -> i32\nwhere I: Iterator<Item = i32> {\n    values.sum()\n}\nassert_eq!(sum_values([1, 2, 3].into_iter()), 6);',q:'What does Iterator::Item describe?',o:['The type yielded by that iterator implementation','The number of items remaining','The allocation size of the iterator','A mandatory String field'],why:'Item is the associated output type of the iterator’s next operation.'}),
 L({id:'dyn-traits',t:'dyn Traits & Dispatch',lab:'lifetimes',s:'Store or call through different concrete implementations behind one shared behavior interface.',i:'A trait object such as &dyn Trait supports dynamic dispatch through a suitable trait. Not every trait is dyn-compatible. The object still has an ownership form, such as a reference or Box.',m:'Use generics for compile-time type relationships and trait objects when runtime heterogeneity is valuable. Choose borrowing or owning storage separately from the dispatch mechanism.',r:'Dynamic dispatch can add indirection and constrain optimization, while generics can increase generated code size. Measure the tradeoff for the actual workload.',tip:'Dynamic dispatch and heap allocation are separate choices: &dyn Trait need not own a heap allocation.',g:['Recognize runtime dispatch','Choose an ownership wrapper','Compare trait objects with generics'],c:'trait Speak { fn speak(&self) -> String; }\nstruct Bird;\nimpl Speak for Bird { fn speak(&self) -> String { "chirp".into() } }\nlet bird = Bird;\nlet speaker: &dyn Speak = &bird;\nprintln!("{}", speaker.speak());',q:'Does &dyn Trait necessarily own a heap allocation?',o:['No, it can borrow an existing value','Yes, every trait object allocates','Only if the trait has one method','It always takes ownership'],why:'A borrowed trait object references an existing value; allocation depends on how the value is stored.'}),
 L({id:'lifetime-parameters',t:'Lifetime Parameters',lab:'lifetimes',s:'Return one of several borrowed inputs while making their validity relationship explicit.',i:'Lifetime annotations describe relationships among references; they do not extend the life of a value. The compiler uses those relationships to ensure the returned borrow remains valid.',m:'Annotate a function when elision cannot express the needed relationship. For a function returning either input, a shared lifetime can describe the interval in which both inputs are usable.',r:'A lifetime parameter is not a runtime timer. If a caller needs a result independent of the inputs, an owned return value may be the right API.',tip:'Annotations explain validity relationships; they do not create longer-lived storage.',g:['Describe relationships between borrows','Avoid treating lifetimes as duration controls','Choose owned output when needed'],c:'fn longer<\'a>(left: &\'a str, right: &\'a str) -> &\'a str {\n    if left.len() >= right.len() { left } else { right }\n}\nlet answer = longer("rust", "go");\nassert_eq!(answer, "rust");',q:'What does a lifetime annotation do?',o:['Describes a reference-validity relationship checked by the compiler','Keeps a local allocation alive automatically','Sets a timeout in milliseconds','Disables dangling-reference checks'],why:'Annotations communicate constraints; they do not alter how long the owner actually exists.'}),
 L({id:'borrowed-structs-static',t:'Borrowed Structs & static',lab:'lifetimes',s:'Store a view into another value and understand what a static lifetime requirement really means.',i:'A struct holding a reference can carry a lifetime parameter tied to its source. A static reference is valid for the program’s duration, while a T: static bound means T contains no non-static borrowed data; owned values can satisfy it.',m:'Use borrowed structs for temporary views. Use owned fields when the structure should move independently or be stored beyond the source’s scope.',r:'Adding static to silence an error does not make borrowed local data permanent. A static type bound also does not require an owned value to live forever.',tip:'Distinguish a reference lifetime from a bound on the references a type may contain.',g:['Model borrowed views','Interpret static bounds correctly','Choose ownership for independent storage'],c:'struct Label<\'a> { text: &\'a str }\nlet title = String::from("Rust School");\nlet label = Label { text: &title };\nprintln!("{}", label.text);',q:'Does T: static mean every value of T must live forever?',o:['No, it means T contains no shorter-lived borrowed data','Yes, such values can never be dropped','Yes, all such values are global variables','No, it disables all lifetime checks'],why:'Owned types such as String can satisfy the bound and still be dropped normally.'})
 ]},
 {id:'iterators-smart-pointers',title:'Iterators, Closures & Smart Pointers',color:'#bd6585',lessons:[
 L({id:'iterator-adapters',t:'Iterators & Lazy Adapters',lab:'iterators',s:'Describe a sequence transformation without manually managing an index and output loop.',i:'Iterator adapters such as map and filter usually create lazy iterator values. Work occurs when the iterator is driven by a consumer such as collect, sum, or a for loop.',m:'Choose iter for shared references, iter_mut for mutable references, or into_iter when ownership should be consumed. Compose a small readable pipeline and specify the output collection when inference needs help.',r:'Lazy composition can avoid intermediate collections, but it is not automatically faster than every loop. Clarity and measured behavior both matter.',tip:'Know what item type flows through each stage.',g:['Drive lazy adapters with a consumer','Choose borrowed or owned iteration','Track item types through a pipeline'],c:'let values = vec![1, 2, 3, 4];\nlet squares: Vec<_> = values.iter()\n    .copied().filter(|n| n % 2 == 0)\n    .map(|n| n * n).collect();\nassert_eq!(squares, vec![4, 16]);',q:'When does a lazy map adapter normally perform its work?',o:['When a consumer drives the iterator','Immediately when map is constructed','Only after the program exits','Only inside an unsafe block'],why:'Adapters describe a transformation that runs as items are requested.'}),
 L({id:'closures',t:'Closures & Captures',lab:'borrowing',s:'Pass a small operation that can use values from its surrounding scope.',i:'Closures capture their environment by borrowing or moving as required, with move requesting ownership of captured values. Fn, FnMut, and FnOnce describe how the closure can be called based on its behavior.',m:'Use a closure for local behavior and inspect whether it reads, mutates, or consumes captured values. A move closure can still implement Fn if calling it does not consume its captures.',r:'Capture mode and call capability are related but not identical. A closure’s environment also determines borrowing and thread-safety constraints.',tip:'move describes capture, not a rule that the closure can only be called once.',g:['Read captured environment access','Distinguish Fn, FnMut, and FnOnce','Separate move capture from call count'],c:'let prefix = String::from("Hello");\nlet greet = move |name: &str| format!("{prefix}, {name}");\nprintln!("{}", greet("Ava"));\nprintln!("{}", greet("Noah"));',q:'Can a move closure be called more than once?',o:['Yes, if its body does not consume its captured values on a call','No, move always means FnOnce only','Only if it captures nothing','Only in an unsafe block'],why:'A move capture owns its environment, but the body may merely borrow that owned environment when called.'}),
 L({id:'box',t:'Box & Owned Indirection',s:'Give an owned value a stable indirection or represent recursive structures with finite size.',i:'Box<T> owns a value through a heap allocation for ordinary sized values. Indirection lets recursive type definitions have a known outer size. It preserves single-owner semantics.',m:'Use Box when indirection solves a concrete layout or API need. Dereference it through normal operations and let ownership determine when the allocation is released.',r:'Box does not imply shared ownership. Moving a Box transfers its ownership handle rather than cloning the contents.',tip:'Use indirection for a reason, not because every object must live on the heap.',g:['Explain finite-size recursive types','Trace single ownership through a box','Separate moving a handle from cloning data'],c:'enum List { Node(i32, Box<List>), End }\nlet list = List::Node(1, Box::new(List::End));\nmatch list {\n    List::Node(value, _) => println!("{value}"),\n    List::End => {}\n}',q:'Why does Box help define a recursive enum?',o:['The indirection has a known size even though the recursive structure can grow','It makes the enum dynamically typed','It removes every allocation','It automatically shares ownership across threads'],why:'A fixed-size pointer-like owner breaks the infinitely recursive inline layout.'}),
 L({id:'rc-weak',t:'Rc, Weak & Shared Ownership',s:'Several parts of a single-threaded structure need to share one owned value.',i:'Rc<T> provides reference-counted ownership for single-threaded use. Strong owners keep the value alive. Weak references can observe the allocation without creating a strong ownership cycle.',m:'Clone the Rc handle when adding an owner. Use Weak for back-links where a child should not keep its parent alive, and handle upgrade returning None.',r:'Strong Rc cycles can leak allocations because reference counts never reach zero. This is a resource leak, not permission for use-after-free.',tip:'Draw ownership arrows separately from navigation links.',g:['Track strong and weak owners','Recognize reference-count cycles','Handle expired weak references'],c:'use std::rc::Rc;\nlet owner = Rc::new(String::from("shared"));\nlet weak = Rc::downgrade(&owner);\nassert!(weak.upgrade().is_some());\ndrop(owner);\nassert!(weak.upgrade().is_none());',q:'Why use Weak for a parent back-link?',o:['It avoids keeping the parent alive through a strong ownership cycle','It permits unchecked mutable aliasing','It makes Rc thread-safe','It duplicates the parent’s data'],why:'A weak link does not contribute to the strong count that keeps the value alive.'}),
 L({id:'refcell',t:'RefCell & Interior Mutability',lab:'borrowing',s:'A shared owner needs controlled mutation even when compile-time borrowing cannot express the whole access pattern.',i:'RefCell<T> checks borrowing rules at runtime. borrow creates shared access, while borrow_mut requires exclusive access. A conflict panics with these methods; try_borrow variants return errors instead.',m:'Keep borrow guards short and avoid calling code that may reborrow while a guard remains active. Use RefCell only where its single-threaded runtime checking matches the design.',r:'Interior mutability does not abolish the rules. It moves a specific form of checking into runtime and is not a synchronization solution for sharing across threads.',tip:'A RefCell borrow guard holds access rights until the guard is dropped.',g:['Understand runtime borrow checking','Limit guard lifetimes','Choose non-panicking borrow attempts when needed'],c:'use std::cell::RefCell;\nlet count = RefCell::new(0);\n{ let mut value = count.borrow_mut(); *value += 1; }\nassert_eq!(*count.borrow(), 1);',q:'What happens when borrow_mut is called while a conflicting RefCell borrow is active?',o:['It panics; try_borrow_mut can report an error instead','The compiler always rejects that runtime path','The earlier borrow is silently revoked','A second independent value is created'],why:'RefCell enforces borrowing dynamically and reports a violation through panic or a fallible borrowing API.'}),
 L({id:'arc-mutex',t:'Arc & Mutex',lab:'borrowing',s:'Share ownership across threads while coordinating mutation of one common value.',i:'Arc<T> provides atomic reference-counted ownership, not automatic safe mutation of T. Mutex<T> grants exclusive access through a lock guard. Combining them is useful when shared mutable state is genuinely needed.',m:'Clone Arc handles, acquire the lock for a short critical section, and release it before unrelated work. Decide how to handle poisoning or errors in the application.',r:'A correct mutex can prevent data races while the overall program still deadlocks or makes a logically incorrect update. Shared state remains a design responsibility.',tip:'Arc manages lifetime; Mutex manages access.',g:['Separate shared ownership from synchronization','Keep critical sections small','Handle logical concurrency failures'],c:'use std::sync::{Arc, Mutex};\nlet count = Arc::new(Mutex::new(0));\nlet another = Arc::clone(&count);\n{ *another.lock().expect("counter lock poisoned") += 1; }\nassert_eq!(*count.lock().unwrap(), 1);',q:'Does Arc<T> alone make arbitrary mutation of T safe across threads?',o:['No, access still needs suitable synchronization or immutable design','Yes, atomic counting protects all fields','Only when its count is two','It turns every field into an atomic'],why:'Arc protects its ownership count; the contained type must satisfy its own access and thread-safety requirements.'})
 ]},
 {id:'testing-tooling',title:'Testing & Tooling',color:'#8d9841',lessons:[
 L({id:'unit-tests',t:'Unit Tests',level:'beginner',s:'Check a small behavior automatically rather than relying on a manual run after each edit.',i:'Rust’s test harness discovers test functions marked with #[test]. Assertions encode expected behavior, and tests can access private implementation details when placed in suitable child modules.',m:'Test normal values, boundaries, and failure cases. Name tests after the behavior they protect and keep setup small enough to reveal what matters.',r:'Passing tests cover the cases and properties you wrote, not every possible input. Type checking and tests provide complementary evidence.',tip:'A useful test fails for a meaningful behavior change.',g:['Write focused assertions','Cover boundaries and failures','Separate tests from implementation mirroring'],c:'fn double(x: i32) -> i32 { x * 2 }\n#[test]\nfn doubles_zero_and_positive_values() {\n    assert_eq!(double(0), 0);\n    assert_eq!(double(3), 6);\n}',q:'What does a passing unit test prove?',o:['The tested assertion held for that test execution','The entire program has no bugs','All future inputs are correct','Unsafe code is automatically sound'],why:'Tests establish evidence for their selected cases and conditions, not universal correctness.'}),
 L({id:'integration-doc-tests',t:'Integration & Documentation Tests',s:'Verify the public interface the way a caller uses it and keep examples from drifting away from reality.',i:'Integration tests in tests/ are separate crates that use the public API. Rust documentation can contain examples that rustdoc tests, helping keep written usage connected to actual code.',m:'Put public workflows in integration tests and concise usage examples beside public items. Use hidden setup lines in documentation only when they make the visible example clearer.',r:'Documentation tests can catch stale examples, but ignored or non-Rust blocks are not the same as executed examples. State example assumptions.',tip:'An API example is part of the user experience and deserves maintenance.',g:['Test through the public boundary','Keep examples executable where appropriate','Distinguish documented from tested behavior'],c:'/// Returns the next value.\n/// ```\n/// assert_eq!(my_crate::next(2), 3);\n/// ```\npub fn next(value: u32) -> u32 { value + 1 }\n// Replace my_crate with the library crate name.',q:'What interface do ordinary integration tests use?',o:['The crate’s public interface','Every private item without restrictions','Only compiler internals','Only documentation comments'],why:'Integration tests compile as separate crates and therefore exercise the exposed API.'}),
 L({id:'properties-edge-cases',t:'Properties, Boundaries & Fuzzing',s:'A few hand-picked examples may miss malformed input and surprising combinations.',i:'Property-based tests describe invariants over many generated inputs. Fuzzing explores inputs to find failures such as panics or invalid behavior. Both complement example-based tests rather than replacing a clear specification.',m:'State properties carefully, generate valid and invalid inputs intentionally, and retain minimized failing cases. Keep resource limits when testing parsers or untrusted input paths.',r:'A long fuzz run without a failure is evidence within its exploration, not proof that every input is safe or correct.',tip:'A good property comes from the contract, not from repeating the implementation.',g:['Express behavioral invariants','Test malformed input and boundaries','Preserve small regression cases'],c:'fn round_trip(values: &[u8]) {\n    let encoded = encode(values);\n    let decoded = decode(&encoded).expect("valid encoding");\n    assert_eq!(decoded, values);\n}\n// Supply generated inputs to this property.',q:'Which is a useful property for an encoder and decoder pair?',o:['Decoding an encoded valid input recovers that input','Both functions have the same line count','Every output is shorter than every input','No tests ever generate empty input'],why:'A round-trip property expresses an observable relationship required by the format contract.'}),
 L({id:'fmt-clippy',t:'rustfmt & Clippy',level:'beginner',s:'Keep formatting consistent and surface suspicious code patterns before review.',i:'rustfmt applies standard formatting conventions. Clippy provides additional lints for common mistakes and style or performance concerns. Neither is a full behavioral verification system.',m:'Run formatting checks and Clippy in development and CI. Review lint recommendations in context, and document narrow allowances when a deliberate exception is needed.',r:'A clean lint result does not prove correctness. Conversely, blindly applying a suggestion can make an API less appropriate for its intended purpose.',tip:'Use automation for consistency so review can focus on design and behavior.',g:['Separate formatting from semantic linting','Run consistent quality checks','Review exceptions deliberately'],c:'// Terminal quality checks:\n// cargo fmt --check\n// cargo clippy --all-targets -- -D warnings\n// cargo test\nfn main() { println!("Checked and readable"); }',q:'What is rustfmt primarily responsible for?',o:['Consistent source formatting','Proving the algorithm correct','Resolving every dependency vulnerability','Publishing the package'],why:'rustfmt formats source code; behavioral tests and other tools address different concerns.',src:'https://doc.rust-lang.org/clippy/'}),
 L({id:'dependencies-features',t:'Dependencies, Features & Lockfiles',s:'Make a dependency graph reproducible while enabling only the capabilities the application needs.',i:'Cargo.toml declares requirements; Cargo.lock records a resolved graph. Features configure optional capabilities and can be unified across dependencies, so they should generally add behavior rather than represent mutually exclusive modes.',m:'Review dependency provenance, versions, and enabled features. Test supported feature combinations and use appropriate lockfile policy for the package and workflow.',r:'A lockfile fixes selected versions, not the trustworthiness of their code or the whole external build environment. Build scripts and procedural macros can execute code during builds.',tip:'Treat dependencies as code you choose to execute, not passive metadata.',g:['Distinguish requirements from resolution','Understand additive feature behavior','Review build-time execution'],c:'// Cargo.toml example:\n// serde = { version = "1", features = ["derive"] }\n// Terminal: cargo tree -e features\n// CI may use: cargo test --locked',q:'What does Cargo.lock primarily record?',o:['The resolved dependency versions for a build graph','A guarantee that dependencies contain no bugs','Every future compatible release','Only the project’s edition'],why:'The lockfile captures a concrete resolution so subsequent builds can use the same dependency versions.',src:'https://doc.rust-lang.org/cargo/reference/features.html'}),
 L({id:'benchmark-profile',t:'Benchmark & Profile',s:'Find the real bottleneck before rewriting clear Rust into complicated low-level code.',i:'Benchmarks measure selected workloads; profiling attributes time or resource use to program behavior. Reliable comparisons need representative inputs, suitable build settings, and attention to optimizer effects.',m:'Measure a release-like build, repeat runs, and inspect variance. Profile allocations, I/O, and CPU separately when useful. Prevent benchmark setup from dominating the operation being studied.',r:'A microbenchmark win may disappear in the full application. Improvements should preserve correctness and be tested under the workload that matters.',tip:'Optimize the measured bottleneck, then measure again.',g:['Build representative measurements','Separate setup from the measured operation','Connect local improvements to system behavior'],c:'let input = std::hint::black_box(vec![1_u64; 10_000]);\nlet started = std::time::Instant::now();\nlet total: u64 = input.iter().sum();\nstd::hint::black_box(total);\nprintln!("{:?}", started.elapsed());\n// Use a benchmarking harness for robust comparisons.',q:'Why profile before optimizing?',o:['To identify where the actual workload spends resources','To avoid checking correctness','To make every loop unsafe','To guarantee a fixed speedup'],why:'Profiling can reveal that the presumed bottleneck is not the part that limits the application.'})
 ]},
 {id:'concurrency-async',title:'Concurrency & Async',color:'#748198',lessons:[
 L({id:'threads-channels',t:'Threads & Channels',s:'Run independent work concurrently and transfer results without sharing every piece of mutable state.',i:'OS threads can execute concurrently. Channels transfer messages between producers and consumers, often making ownership transfer explicit. Joining a thread observes its completion and possible panic.',m:'Move owned inputs into a worker and return or send owned results. Bound queues where the application needs backpressure instead of allowing unlimited buffering.',r:'Channels can simplify shared-state reasoning, but they do not prevent deadlocks, unbounded work, or incorrect message protocols.',tip:'Design who closes the channel and how the receiver recognizes completion.',g:['Move data into workers','Communicate through explicit messages','Observe worker completion'],c:'let (tx, rx) = std::sync::mpsc::channel();\nlet worker = std::thread::spawn(move || { tx.send(42).unwrap(); });\nassert_eq!(rx.recv().unwrap(), 42);\nworker.join().unwrap();',q:'What does joining a thread let the caller observe?',o:['Completion and whether the thread panicked','Guaranteed success of every external operation','The elimination of all races in the application','Automatic cancellation of unrelated threads'],why:'Join waits for completion and returns an outcome that can report a panic.'}),
 L({id:'send-sync',t:'Send & Sync',lab:'borrowing',s:'Determine which values can cross thread boundaries and which shared references can be used across threads.',i:'Send means ownership of a value can be transferred between threads safely. Sync means a shared reference to the type can be transferred safely. These are unsafe traits whose manual implementations require soundness reasoning.',m:'Prefer types whose safe APIs and auto-trait behavior already express the needed guarantees. Rc and RefCell are not substitutes for Arc and synchronization in cross-thread sharing.',r:'Thread safety is composed from the contained values and APIs. Wrapping a type in Arc does not automatically make arbitrary contents safe to share.',tip:'Do not manually implement Send or Sync merely to silence a compiler error.',g:['Distinguish ownership transfer from shared access','Read thread-safety bounds','Choose suitable cross-thread types'],c:'fn require_send<T: Send>(_: T) {}\nfn require_sync<T: Sync>(_: &T) {}\nrequire_send(String::from("owned"));\nrequire_sync(&42_u32);',q:'What does Sync mean for a type T?',o:['A shared reference &T can be transferred across threads safely','T can always be mutated without synchronization','T must use reference counting','T has no lifetime parameters'],why:'Sync concerns safe shared access through references; it does not grant arbitrary mutation.'}),
 L({id:'locks-atomics',t:'Locks, Atomics & Coordination',lab:'borrowing',s:'Protect a shared update without confusing data-race freedom with a correct concurrent protocol.',i:'Mutexes protect critical sections. Atomic types support indivisible operations with specified memory ordering. Ordering choices affect visibility relationships, not just performance.',m:'Start with a clear lock-based design when appropriate. Use atomics for a well-understood protocol and avoid weakening ordering without a correctness argument.',r:'Even sequentially consistent atomics do not automatically make a multi-step algorithm correct. Multiple locks can still deadlock if acquisition order is inconsistent.',tip:'Specify the invariant protected by a lock or atomic protocol.',g:['Separate atomic operations from whole algorithms','Recognize lock-order deadlocks','Treat memory ordering as correctness'],c:'use std::sync::atomic::{AtomicUsize, Ordering};\nlet count = AtomicUsize::new(0);\ncount.fetch_add(1, Ordering::SeqCst);\nassert_eq!(count.load(Ordering::SeqCst), 1);',q:'Does an atomic counter automatically make all surrounding multi-step logic correct?',o:['No, the complete protocol still needs reasoning','Yes, atomics prevent every concurrency bug','Only when the counter starts at zero','Yes, if the code compiles'],why:'An indivisible operation is only one piece of an algorithm that may have larger ordering and consistency requirements.'}),
 L({id:'async-futures',t:'async, await & Futures',s:'Wait for many I/O operations without assigning a blocked OS thread to every pending request.',i:'An async function returns a future representing work that can be polled. await allows the task to suspend while waiting. A future does not run simply because it was constructed; something must drive it.',m:'Use async for workloads with useful waiting opportunities. Keep blocking operations and long CPU loops from monopolizing executor threads.',r:'Async concurrency is not the same as parallel CPU execution. A single thread can interleave waiting tasks, while CPU parallelism needs suitable execution resources.',tip:'A future is a stateful computation, not a background thread by itself.',g:['Distinguish constructing from driving a future','Understand suspension at await','Separate concurrency from parallelism'],c:'async fn value() -> u32 { 42 }\nasync fn example() {\n    let pending = value();\n    let answer = pending.await;\n    assert_eq!(answer, 42);\n}',q:'Does calling an async function immediately run its body to completion?',o:['No, it creates a future that must be driven','Yes, always on a new OS thread','Yes, before returning the future','Only if its name begins with async'],why:'The returned future represents the computation; polling it through an executor or await drives progress.',src:'https://doc.rust-lang.org/book/ch17-01-futures-and-syntax.html'}),
 L({id:'tokio-runtime',t:'Tokio Tasks & Blocking Work',s:'Run asynchronous I/O tasks on an executor while keeping blocking work from stalling other tasks.',i:'Tokio provides a runtime, I/O facilities, and task scheduling. Spawned tasks cooperate with the runtime. Blocking a worker thread can delay unrelated tasks scheduled on that thread.',m:'Enable the required Cargo features, await spawned task outcomes, and route appropriate synchronous work through spawn_blocking. For large CPU workloads, use bounded concurrency and a suitable execution strategy.',r:'Spawning more tasks is not a capacity plan. Runtime threads, blocking work, queues, and external services can all become bottlenecks.',tip:'Keep task lifetimes and resource limits visible to the part of the application that owns them.',g:['Use a runtime to drive tasks','Separate blocking work from async workers','Observe task failures and capacity'],c:'#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let task = tokio::spawn(async { 21 * 2 });\n    assert_eq!(task.await?, 42);\n    Ok(())\n}',q:'Why avoid blocking an async runtime worker thread?',o:['It can prevent other tasks on that thread from making progress','It automatically corrupts every allocation','It converts all futures into OS threads','It disables Send checking'],why:'Blocking occupies the worker instead of yielding it to other runnable tasks.',src:'https://docs.rs/tokio/latest/tokio/task/index.html'}),
 L({id:'async-cancellation',t:'Cancellation & Graceful Shutdown',s:'Stop work deliberately without leaving half-completed external actions or silently detached tasks.',i:'Dropping a pending future stops polling it and drops its owned state; that does not undo external effects. Tokio task abortion requests cancellation, and awaiting the handle observes completion. Dropping a JoinHandle alone detaches its task.',m:'Define cancellation-safe boundaries and a shutdown signal. Stop accepting new work, let selected tasks finish or cancel them, and observe their outcomes. Started spawn_blocking work cannot generally be aborted through its handle.',r:'A timeout means the caller stopped waiting according to a policy, not necessarily that all remote work was reversed. Transactional or idempotent designs may be needed.',tip:'Cancellation is a protocol decision, not an automatic rollback.',g:['Track task ownership during shutdown','Distinguish cancellation from rollback','Handle work that cannot be promptly stopped'],c:'let task = tokio::spawn(async {\n    tokio::time::sleep(std::time::Duration::from_secs(30)).await;\n});\ntask.abort();\nlet outcome = task.await;\n// Inspect outcome; the task may have completed before the abort.',q:'What happens when an ordinary Tokio JoinHandle is dropped?',o:['The task is detached rather than automatically cancelled','The task always rolls back external effects','Every runtime task stops immediately','The task becomes a blocking thread'],why:'Dropping the handle loses the ability to await that task; cancellation requires an explicit policy or runtime shutdown.',src:'https://docs.rs/tokio/latest/tokio/task/index.html'})
 ]},
 {id:'systems-safety',title:'Systems & Safety',color:'#a16a94',lessons:[
 L({id:'memory-layout',t:'Memory, Layout & Allocation',s:'Reason about storage and data layout without assuming the language promises more than it does.',i:'Values have size and alignment requirements. Containers such as Vec manage allocations separately from their small owning handles. Default Rust representation does not promise a stable field layout suitable for an external ABI.',m:'Inspect sizes when useful, use repr(C) for an appropriate C-compatible layout contract, and consider padding and alignment. Do not infer ownership or pointer validity from a numeric address alone.',r:'A layout attribute is one part of interoperability. It does not make arbitrary field types valid for C or justify reading uninitialized padding.',tip:'Distinguish language guarantees from observations in one build.',g:['Understand size and alignment','Separate handles from owned buffers','Use explicit representation when a boundary needs it'],c:'#[repr(C)]\nstruct Point { x: f64, y: f64 }\nprintln!("size: {}", std::mem::size_of::<Point>());\nprintln!("alignment: {}", std::mem::align_of::<Point>());',q:'Does default Rust struct layout promise a stable C ABI?',o:['No, an appropriate explicit representation and compatible fields are needed','Yes, all structs are C-compatible','Only if fields are public','Yes, if the program is optimized'],why:'Rust’s default representation is not a general C layout contract.',src:'https://doc.rust-lang.org/reference/type-layout.html'}),
 L({id:'unsafe-invariants',t:'unsafe & Safety Invariants',level:'advanced',s:'Some low-level operations require facts the compiler cannot verify from the type system alone.',i:'unsafe permits specific operations while leaving the programmer responsible for their preconditions. It does not turn off all checks or make undefined behavior acceptable. A safe wrapper must prevent safe callers from violating its invariant.',m:'Keep unsafe regions small, document the exact safety argument, and prefer safe standard APIs where they already solve the problem. Review both callers and encapsulation boundaries.',r:'A passing test cannot prove an unsafe abstraction sound for every safe caller. Undefined behavior can affect the entire program, not only the unsafe block.',tip:'Write the safety argument before the unsafe operation.',g:['Identify unverifiable preconditions','Encapsulate an invariant behind a safe API','Distinguish unsafe permission from correctness'],c:'let values = [10, 20, 30];\nlet index = 1;\n// SAFETY: index is within this array’s bounds.\nlet value = unsafe { values.get_unchecked(index) };\nassert_eq!(*value, 20);\n// Prefer values.get(index) unless unchecked access is justified.',q:'What does an unsafe block mean?',o:['The programmer must uphold the preconditions of specific unsafe operations','Undefined behavior is allowed inside the block','All type checks disappear','The code is automatically faster'],why:'Unsafe shifts responsibility for certain guarantees; it never authorizes undefined behavior.',src:'https://doc.rust-lang.org/reference/behavior-considered-undefined.html'}),
 L({id:'raw-pointers',t:'Raw Pointers & Valid Access',level:'advanced',lab:'lifetimes',s:'Interact with memory addresses while preserving validity, alignment, and aliasing requirements.',i:'Raw pointers can exist in states that references cannot, but dereferencing them requires an unsafe operation with valid preconditions. Creating or copying a pointer does not extend the lifetime of its allocation.',m:'Derive pointers from known storage, keep the owner alive, and avoid conflicting access. Convert to references only when the stronger reference guarantees truly hold.',r:'A non-null pointer is not automatically valid to dereference. The memory can be freed, misaligned, outside the allocation, or incompatible with the access rules.',tip:'Pointer validity is a relationship with an allocation and an access, not just a number.',g:['Separate pointer existence from dereference validity','Preserve owner lifetimes','Respect alignment and aliasing'],c:'let value = 42_u32;\nlet pointer: *const u32 = &value;\n// SAFETY: value is alive, aligned, initialized, and only read here.\nlet copied = unsafe { *pointer };\nassert_eq!(copied, 42);',q:'Is a non-null raw pointer necessarily safe to dereference?',o:['No, lifetime, alignment, validity, and access conditions still matter','Yes, non-null is the only condition','Only in a release build','Yes, if it points to an integer address'],why:'Non-nullness alone does not establish that the memory supports the intended access.',src:'https://doc.rust-lang.org/reference/behavior-considered-undefined.html'}),
 L({id:'ffi',t:'FFI & External Contracts',level:'advanced',s:'Call a foreign function whose signature and memory rules Rust cannot validate by inspecting its implementation.',i:'FFI requires agreement on ABI, types, ownership, and error behavior. In Edition 2024, extern blocks are marked unsafe to emphasize responsibility for their declarations. Boundary layout and pointer contracts remain separate obligations.',m:'Write declarations from the foreign API’s exact contract, document ownership and lifetimes, and wrap unsafe calls behind a checked interface when possible. Do not allow incompatible unwinding behavior across a boundary.',r:'Correct syntax does not prove an FFI declaration matches the linked function. A wrong signature can cause undefined behavior even when the Rust source compiles.',tip:'Treat foreign declarations as assertions you must verify.',g:['Match ABI and data layout','Document cross-language ownership','Wrap foreign preconditions deliberately'],c:'unsafe extern "C" {\n    fn foreign_process(data: *const u8, length: usize) -> i32;\n}\n// Requires a linked implementation with this exact ABI and contract.\n// A safe wrapper must validate the data and ownership requirements.',q:'What does an unsafe extern block establish by itself?',o:['Only the declaration’s syntax, not that the foreign signature is correct','That every foreign function is safe to call','That C memory is automatically owned by Rust','That unwinding is always compatible'],why:'The programmer must verify the declaration and boundary contract against the foreign implementation.',src:'https://doc.rust-lang.org/edition-guide/rust-2024/unsafe-extern.html'}),
 L({id:'panic-boundaries',t:'Panics, Invariants & Recovery',s:'Decide which failures belong in Result and which indicate a violated assumption or an unrecoverable state.',i:'A panic is different from an ordinary returned error. Depending on configuration, panic behavior may unwind or abort. catch_unwind has a narrow role and does not turn every failure into safe application recovery.',m:'Return Result for expected failures such as invalid external input. Use assertions for invariants and design boundaries that do not expose a corrupted logical state after partial work.',r:'Memory safety does not guarantee transactional behavior. Cleanup and recovery must account for panic strategy, foreign boundaries, and external side effects.',tip:'Do not use panics as the normal control flow for routine user mistakes.',g:['Separate expected errors from invariant violations','Understand unwind versus abort','Design recovery around state consistency'],c:'fn percentage(value: u8) -> Result<u8, &\'static str> {\n    if value > 100 { return Err("percentage must be at most 100"); }\n    Ok(value)\n}\nassert!(percentage(120).is_err());',q:'What is usually appropriate for routine invalid user input?',o:['A recoverable Result with a meaningful error','A panic used as ordinary control flow','An unchecked raw-pointer write','Ignoring the input silently'],why:'Expected invalid input is a runtime outcome callers should be able to report or handle.',src:'https://doc.rust-lang.org/book/ch09-03-to-panic-or-not-to-panic.html'}),
 L({id:'performance-ownership',t:'Performance through Ownership',level:'advanced',lab:'borrowing',s:'Reduce avoidable allocation and copying without making the program harder to reason about.',i:'Ownership choices affect whether data is moved, borrowed, cloned, or shared. Zero-cost abstraction is a design goal, not a guarantee that every high-level expression has the same cost.',m:'Profile before changing APIs. Reuse buffers where appropriate, reserve sensible capacity, and borrow existing data when independence is not required. Measure whole-workload impact.',r:'Avoiding one clone can introduce complicated lifetimes or synchronization that costs more elsewhere. A clear owned boundary can be the right tradeoff.',tip:'Optimize measured costs while preserving an understandable ownership story.',g:['Find allocation and copying costs','Use borrowing or reuse where justified','Evaluate complexity as well as speed'],c:'fn append_line(output: &mut String, line: &str) {\n    output.push_str(line);\n    output.push(\'\n\');\n}\nlet mut output = String::with_capacity(128);\nappend_line(&mut output, "reused buffer");',q:'When should you replace a simple owned API with a more complex borrowed one?',o:['When the lifetime relationship is appropriate and measured benefits justify it','Whenever a borrow can be written','Only when every caller is unsafe','Whenever the file has more than ten lines'],why:'Ownership design balances performance, independence, and complexity rather than blindly minimizing allocations.'})
 ]},
 {id:'services-delivery',title:'Services & Delivery',color:'#b1804f',lessons:[
 L({id:'serde',t:'Serde & Data Boundaries',s:'Convert external data into typed values without treating successful parsing as complete domain validation.',i:'Serde defines serialization and deserialization traits used by formats such as JSON. Deriving Deserialize checks structural compatibility, but a numeric field can still violate a business rule.',m:'Deserialize into an input type, validate domain constraints, and convert into a stronger internal type. Decide how to handle unknown fields, optional values, and compatibility changes.',r:'Typed input reduces accidental misuse but does not establish authorization, trust, or semantic correctness. Error responses should avoid exposing sensitive internals.',tip:'Parsing establishes structure; validation establishes the domain contract.',g:['Separate formats from data traits','Validate after structural parsing','Design compatible external contracts'],c:'#[derive(serde::Deserialize)]\nstruct CreateItem { name: String, quantity: u32 }\nlet input: CreateItem = serde_json::from_str(payload)?;\nif input.name.trim().is_empty() { return Err("name required".into()); }\n// Continue with domain validation.',q:'Does successful JSON deserialization prove an input is valid for the business domain?',o:['No, semantic validation and authorization are still separate','Yes, all numeric values are meaningful','Only if the fields are public','Yes, when derive is used'],why:'A structurally valid value can still violate domain constraints or lack permission for the requested operation.',src:'https://serde.rs/'}),
 L({id:'axum-http',t:'HTTP Services with Axum',s:'Expose a small typed HTTP endpoint and connect it to an asynchronous runtime.',i:'Axum uses routes, async handlers, extractors, and response conversion. Extractors obtain request data, while application state can be supplied explicitly. Middleware handles cross-cutting concerns.',m:'Build a Router, bind a Tokio TCP listener, and serve it with axum::serve. Add request limits, authentication where needed, error mapping, and graceful shutdown for a real service.',r:'An endpoint returning 200 is not evidence that every input or dependency failure is handled. Test contracts, timeouts, and failure paths.',tip:'Keep transport handling thin and domain logic independently testable.',g:['Connect routes to handlers','Use typed request and response boundaries','Separate service wiring from business behavior'],c:'use axum::{Router, routing::get};\nlet app = Router::new().route("/health", get(|| async { "ok" }));\nlet listener = tokio::net::TcpListener::bind("127.0.0.1:3000").await?;\naxum::serve(listener, app).await?;\n// Run inside an async function with the required Cargo dependencies.',q:'What is a useful reason to keep domain logic outside an HTTP handler?',o:['It can be tested and reused independently of transport details','It removes the need for input validation','It guarantees network availability','It makes every request infallible'],why:'Separating concerns lets the same domain behavior be exercised without constructing HTTP requests.',src:'https://docs.rs/axum/latest/axum/'}),
 L({id:'sql-transactions',t:'SQL, Pools & Transactions',s:'Persist related changes without leaving the database in a half-completed state.',i:'A connection pool manages reusable database connections. A transaction groups operations with database-defined isolation and atomicity. Parameter binding separates values from SQL syntax.',m:'Use bound parameters, acquire a transaction, perform related statements, and commit explicitly when all steps succeed. Handle errors and retries according to the database and driver contract.',r:'Transactions do not make arbitrary external API calls atomic with database writes. Isolation levels and retry behavior matter under concurrent activity.',tip:'Keep transaction boundaries aligned with the invariant you are protecting.',g:['Use bound parameters','Commit related database work as a unit','Recognize external-side-effect boundaries'],c:'let mut tx = pool.begin().await?;\nsqlx::query("UPDATE inventory SET quantity = quantity - $1 WHERE id = $2")\n    .bind(amount).bind(item_id).execute(&mut *tx).await?;\ntx.commit().await?;\n// PostgreSQL-style placeholders; validate inventory invariants separately.',q:'Why bind SQL values instead of formatting them into a query string?',o:['To keep values separate from SQL syntax','To guarantee the transaction never fails','To remove all database constraints','To make every query use an index'],why:'Parameter binding avoids treating supplied values as executable query syntax.',src:'https://docs.rs/sqlx/latest/sqlx/struct.Transaction.html'}),
 L({id:'logging-observability',t:'Structured Logs & Tracing',s:'Understand a service failure across requests and asynchronous work without logging sensitive data indiscriminately.',i:'Structured events attach named fields, while spans describe a unit of work and its context. Logs, metrics, and traces answer related but distinct operational questions.',m:'Record request identifiers, operation names, outcomes, and durations with appropriate sampling and retention. Use instrumentation that preserves async context correctly rather than holding an entered span guard across unrelated awaits.',r:'More logs do not automatically produce observability. A useful signal has an owner, a question it answers, and a safe handling policy.',tip:'Log enough context to diagnose a failure without copying secrets or entire private payloads.',g:['Use structured operational context','Correlate work across boundaries','Avoid unsafe or noisy logging'],c:'#[tracing::instrument(skip(pool))]\nasync fn load_item(pool: &Pool, item_id: i64) -> Result<Item, Error> {\n    let item = fetch_item(pool, item_id).await?;\n    tracing::info!(item_id, "item loaded");\n    Ok(item)\n}',q:'Why use named fields in structured logs?',o:['They can be filtered and correlated without parsing arbitrary prose','They make all data safe to expose','They eliminate the need for metrics','They guarantee the service has no errors'],why:'Structured fields make operational events easier to query and relate across components.',src:'https://docs.rs/tracing/latest/tracing/'}),
 L({id:'ci-deployment',t:'CI, Containers & Deployment',s:'Turn a tested source revision into an observable, reproducible release with a path back if it fails.',i:'CI runs agreed checks on changes; deployment promotes a selected artifact into an environment. A container packages a runtime image, but configuration, credentials, network policy, and external services remain separate concerns.',m:'Run formatting, linting, tests, and a release build with controlled dependencies. Package the artifact for the target environment, provide health checks, and plan graceful shutdown and rollback.',r:'A successful build does not establish production readiness. Target libraries, migration compatibility, operational limits, and runtime configuration need verification.',tip:'Deploy the exact artifact that passed the release checks.',g:['Create a repeatable release pipeline','Separate artifacts from secrets and configuration','Plan health checks and rollback'],c:'// Example CI sequence:\n// cargo fmt --check\n// cargo clippy --all-targets -- -D warnings\n// cargo test --locked\n// cargo build --release --locked\n// Package and smoke-test the resulting target-specific artifact.',q:'Which artifact should be promoted to production?',o:['The exact versioned artifact that passed release checks','A freshly edited local binary with no recorded source','Whatever file is newest on a laptop','A binary for any target architecture'],why:'Artifact identity connects evaluation evidence to the deployed release.',src:'https://doc.rust-lang.org/cargo/guide/continuous-integration.html'}),
 L({id:'publish-crate',t:'Publish a Reusable Crate',s:'Share a library with a public interface, useful documentation, and deliberate compatibility expectations.',i:'Publishing uploads a versioned package to a registry. Public APIs, feature behavior, license information, and documentation become part of the consumer contract. A published version cannot simply be overwritten with different contents.',m:'Review included files and metadata, test supported features, and run cargo publish --dry-run before an authorized publication. Keep registry credentials out of source control and logs.',r:'A successful package check does not validate every downstream use. Follow semantic-versioning expectations and document compatibility requirements, including supported compiler versions where relevant.',tip:'Treat publication as a release commitment, not a file upload experiment.',g:['Review the public contract','Verify the packaged contents','Plan versioning and credential handling'],c:'// Cargo.toml metadata: description, license, repository, readme\n// Terminal: cargo package --list\n// Terminal: cargo publish --dry-run\n// Publish only after reviewing the version and package contents.',q:'Why run cargo publish --dry-run before a release?',o:['To verify packaging and build checks without uploading the version','To reserve every possible crate name','To overwrite an existing published version','To make all API changes backward-compatible'],why:'The dry run checks the package before the irreversible publication step.',src:'https://doc.rust-lang.org/cargo/reference/publishing.html'})
 ]},
 {id:'projects',title:'End-to-End Projects',color:'#7d78a8',lessons:[
 L({id:'project-cli',t:'Project: A Search CLI',s:'Build a command-line tool that reads a file, finds matching lines, and reports failures with useful exit behavior.',i:'Keep argument parsing and terminal output at the edge. Put search behavior in a library function that borrows its inputs and returns a clearly defined result.',m:'Start with substring matching, then add tests for empty input, Unicode text, and no matches. Handle file errors with Result and distinguish expected outcomes from execution failures.',r:'A useful CLI has predictable output, documented options, and stable exit behavior. Large files may require streaming rather than reading everything at once.',tip:'A small reusable core makes a command-line project easier to test and extend.',g:['Separate CLI wiring from logic','Design a borrowed search API','Handle file and argument failures'],c:'fn search<\'a>(query: &str, text: &\'a str) -> Vec<&\'a str> {\n    text.lines().filter(|line| line.contains(query)).collect()\n}\nassert_eq!(search("Rust", "Learn Rust\nHello"), vec!["Learn Rust"]);',q:'Why can this search function return borrowed line slices?',o:['The returned slices refer to the caller’s text with a related lifetime','It secretly copies the whole file','The function’s local variables live forever','Every line is a static string'],why:'The output lifetime is tied to the input text that owns or stores the line data.',lab:'lifetimes'}),
 L({id:'project-config',t:'Project: Typed Configuration',s:'Load configuration from an external format and reject invalid settings before starting the application.',i:'Separate a permissive input representation from a validated internal configuration. Parsing, defaults, semantic checks, and secret handling are distinct stages.',m:'Deserialize the file, validate ranges and relationships, and construct a type whose fields satisfy the service’s invariants. Test missing fields, invalid values, and compatibility changes.',r:'Starting with invalid configuration can produce confusing runtime failures. A clear startup error should explain the problem without printing confidential values.',tip:'Validate once at the boundary and pass a stronger type inward.',g:['Create a typed configuration boundary','Validate relationships between fields','Report safe startup errors'],c:'struct Config { port: u16, workers: usize }\nfn validate(port: u16, workers: usize) -> Result<Config, &\'static str> {\n    if workers == 0 { return Err("workers must be positive"); }\n    Ok(Config { port, workers })\n}',q:'What should happen after structural configuration parsing?',o:['Validate domain constraints before using the configuration','Assume every parsed value is operationally valid','Print all secrets for debugging','Disable error handling'],why:'A type-compatible configuration can still violate operational rules such as positive worker counts.'}),
 L({id:'project-pipeline',t:'Project: A Bounded Worker Pipeline',s:'Process many jobs concurrently without allowing an unlimited queue to consume memory.',i:'A pipeline has producers, workers, and result handling. Ownership transfer through bounded queues can provide backpressure and make completion responsibilities explicit.',m:'Choose queue capacity and worker count from the workload. Define how producers finish, how workers report failures, and how the coordinator joins every worker before exiting.',r:'A bounded channel limits queued messages, not necessarily all memory or external resource use. Each job still needs sensible limits and cancellation behavior.',tip:'Design termination and error propagation before increasing concurrency.',g:['Bound queued work','Transfer job ownership clearly','Observe every worker’s completion'],c:'let (tx, rx) = std::sync::mpsc::sync_channel(8);\nlet worker = std::thread::spawn(move || {\n    for job in rx { println!("processing {job}"); }\n});\ntx.send(1).unwrap(); drop(tx);\nworker.join().unwrap();',q:'What happens when a bounded channel is full under a blocking send policy?',o:['The producer waits until capacity is available or an error occurs','The queue grows without limit','Every worker is automatically cancelled','The message becomes a shared mutable reference'],why:'Blocking on capacity provides backpressure instead of silently accumulating unlimited queued work.'}),
 L({id:'project-async-client',t:'Project: An Async Fetcher',s:'Fetch a controlled set of remote resources without overwhelming the local runtime or the remote service.',i:'Concurrent requests need limits, timeouts, response-size controls, and a clear error policy. Async I/O allows waiting work to overlap, but it does not remove network failures.',m:'Use a reusable client, validate the allowed destinations, bound concurrency, and inspect response status before consuming a body. Apply retries only where their semantics are safe.',r:'A timeout does not guarantee the remote server stopped processing. Retrying non-idempotent operations can duplicate effects unless the protocol prevents it.',tip:'Concurrency, retries, and cancellation must be designed together.',g:['Bound asynchronous I/O','Handle status and body limits','Retry according to operation semantics'],c:'let response = client.get(url).send().await?;\nlet response = response.error_for_status()?;\n// Enforce a response-size policy before unbounded buffering.\nlet body = response.bytes().await?;\nprocess(body)?;\n// Surround with configured timeouts and bounded concurrency.',q:'Why is blindly retrying every failed request unsafe?',o:['A prior attempt may have performed a non-idempotent effect','All network failures are permanent','Retries cannot run in async code','Rust automatically duplicates every request'],why:'A failed observation does not always mean the remote operation did nothing; the protocol must define safe retry behavior.',src:'https://docs.rs/reqwest/latest/reqwest/',lab:'borrowing'}),
 L({id:'project-service',t:'Project: A Persistent REST Service',s:'Connect typed HTTP requests, domain validation, and transactional storage into a small maintainable service.',i:'The transport layer parses and maps responses; the domain layer enforces rules; the persistence layer manages queries and transactions. Keeping these boundaries visible improves testing and error handling.',m:'Build one complete operation before expanding the API. Add authorization where required, bound request bodies, bind SQL values, and test success, invalid input, conflicts, and dependency failures.',r:'A service is more than a happy-path handler. Observability, migrations, shutdown, configuration, and deployment checks complete the operational contract.',tip:'Test the failure path with the same care as the successful response.',g:['Connect typed boundaries end to end','Preserve transaction and authorization rules','Prepare the service for operations'],c:'async fn create_item(\n    State(state): State<AppState>, Json(input): Json<CreateItem>,\n) -> Result<Json<Item>, ApiError> {\n    let command = validate(input)?;\n    Ok(Json(state.items.create(command).await?))\n}\n// Application-specific types implement the documented contracts.',q:'Which concern should not be skipped merely because a handler compiles?',o:['Authorization and domain validation','The existence of semicolons in source','The choice of editor theme','The number of source files'],why:'Compilation does not establish permission or business validity for external requests.',src:'https://docs.rs/axum/latest/axum/',lab:'borrowing'}),
 L({id:'project-library',t:'Project: A Library You Can Ship',s:'Turn a useful core algorithm into a documented crate with a stable public contract and a reproducible release.',i:'A reusable library needs clear ownership choices, structured errors, examples, tests, and intentional visibility. Consumers should not need to understand internal files to use the API correctly.',m:'Define the smallest useful interface, test it from an integration-test crate, document invariants, and verify the packaged release. Review feature combinations and compatibility before publishing.',r:'Shipping begins a maintenance relationship. Bug fixes, supported compiler versions, security reports, and versioning policy matter after the first upload.',tip:'A strong public API makes correct use easy and incorrect use difficult.',g:['Design a coherent reusable interface','Verify documentation and packaged contents','Plan compatibility and maintenance'],c:'pub struct Counter { value: u64 }\nimpl Counter {\n    pub fn new() -> Self { Self { value: 0 } }\n    pub fn value(&self) -> u64 { self.value }\n    pub fn increment(&mut self) { self.value = self.value.saturating_add(1); }\n}',q:'What is part of a reusable crate’s public contract?',o:['Ownership behavior, errors, documentation, and compatibility expectations','Only its download count','Only the author’s local file layout','Only whether cargo build succeeds'],why:'Consumers depend on how an API behaves and evolves, not merely on its ability to compile.',src:'https://doc.rust-lang.org/cargo/reference/publishing.html'})
 ]}
];

export const lessons=modules.flatMap(module=>module.lessons);
